import ast
import unittest


CLEAN = {
    "models": "class Job:\n    pass\n",
    "errors": "class AppError(Exception):\n    pass\n",
    "pipeline": "from models import Job\nfrom errors import AppError\n",
    "runners": "from pipeline import Job\nfrom errors import AppError\n",
    "cli": "from runners import Job\nfrom errors import AppError\n",
    "registry": "from typing import Callable\n\nHANDLERS: dict[str, Callable] = {}\n",
    "handler_csv": (
        "from registry import HANDLERS\n\n\n"
        "def handle(path):\n"
        "    return path\n\n\n"
        "HANDLERS['csv'] = handle\n"
    ),
}

LAYERS = [["cli"], ["runners"], ["pipeline"], ["models", "errors"]]


def top_level_imports(source):
    found = set()
    for node in ast.parse(source).body:
        if isinstance(node, ast.Import):
            for alias in node.names:
                found.add(alias.name.split(".")[0])
        elif isinstance(node, ast.ImportFrom):
            if node.module:
                found.add(node.module.split(".")[0])
            else:
                for alias in node.names:
                    found.add(alias.name.split(".")[0])
    return found


def build_graph(sources):
    known = set(sources)
    return {name: sorted(top_level_imports(text) & known) for name, text in sources.items()}


def find_cycle(graph):
    color = {}
    stack = []

    def visit(node):
        color[node] = "gray"
        stack.append(node)
        for dependency in graph.get(node, ()):
            if color.get(dependency) == "gray":
                return stack[stack.index(dependency):] + [dependency]
            if dependency in graph and dependency not in color:
                found = visit(dependency)
                if found:
                    return found
        stack.pop()
        color[node] = "black"
        return None

    for node in sorted(graph):
        if node not in color:
            found = visit(node)
            if found:
                return found
    return None


def layer_violations(graph, layers):
    rank = {module: index for index, layer in enumerate(layers) for module in layer}
    violations = []
    for module in sorted(graph):
        if module not in rank:
            continue
        for dependency in graph[module]:
            if dependency in rank and rank[dependency] < rank[module]:
                violations.append((module, dependency))
    return violations


def registry_violations(graph, registry, handlers):
    return [
        (registry, dependency)
        for dependency in graph.get(registry, [])
        if dependency in handlers
    ]


def side_effects(source):
    problems = []
    for node in ast.parse(source).body:
        if isinstance(
            node,
            (ast.Import, ast.ImportFrom, ast.FunctionDef, ast.AsyncFunctionDef,
             ast.ClassDef, ast.Assign, ast.AnnAssign),
        ):
            continue
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant):
            continue
        problems.append(type(node).__name__)
    return problems


class BoundaryTest(unittest.TestCase):
    def test_clean_layers_have_no_cycle(self):
        self.assertIsNone(find_cycle(build_graph(CLEAN)))

    def test_clean_layers_have_no_violation(self):
        self.assertEqual(layer_violations(build_graph(CLEAN), LAYERS), [])

    def test_reverse_dependency_is_flagged(self):
        broken = dict(CLEAN)
        broken["models"] = "from pipeline import Job\n\n\nclass Job:\n    pass\n"
        self.assertEqual(
            layer_violations(build_graph(broken), LAYERS),
            [("models", "pipeline")],
        )

    def test_registry_may_not_import_concrete_handlers(self):
        handlers = {"handler_csv"}
        self.assertEqual(registry_violations(build_graph(CLEAN), "registry", handlers), [])
        broken = dict(CLEAN)
        broken["registry"] = "from handler_csv import handle\n\nHANDLERS = {'csv': handle}\n"
        self.assertEqual(
            registry_violations(build_graph(broken), "registry", handlers),
            [("registry", "handler_csv")],
        )
        self.assertEqual(
            find_cycle(build_graph(broken)),
            ["handler_csv", "registry", "handler_csv"],
        )

    def test_top_level_side_effects_are_flagged(self):
        clean = "import os\n\nVERSION = '1'\n\n\ndef run():\n    return os.getcwd()\n"
        self.assertEqual(side_effects(clean), [])
        self.assertEqual(side_effects("print('register')\nVERSION = '1'\n"), ["Expr"])
        self.assertEqual(side_effects("if True:\n    VERSION = '1'\n"), ["If"])

    def test_handler_depends_on_registry_not_the_reverse(self):
        graph = build_graph(CLEAN)
        self.assertEqual(graph["handler_csv"], ["registry"])
        self.assertEqual(graph["registry"], [])


if __name__ == "__main__":
    unittest.main()

