import unittest
from typing import NotRequired, Required, TypedDict, get_type_hints


class Point(TypedDict):
    x: int
    y: int


class Profile(TypedDict, total=False):
    name: str
    age: NotRequired[int]
    score: Required[float]


def render(value):
    if not isinstance(value, dict):
        raise TypeError("expected dict")
    missing = Point.__required_keys__ - value.keys()
    if missing:
        raise TypeError(f"missing keys: {sorted(missing)}")
    return f"({value['x']}, {value['y']})"


class TypedDictTest(unittest.TestCase):
    def test_typeddict_instances_are_plain_dicts(self):
        point = Point(x=1, y=2)
        self.assertIsInstance(point, dict)
        self.assertIs(type(point), dict)

    def test_constructor_ignores_missing_and_extra_keys(self):
        self.assertEqual(Point(x=1), {"x": 1})
        self.assertEqual(Point(x=1, y=2, z=3), {"x": 1, "y": 2, "z": 3})
        self.assertEqual(Point(x="a", y=[1]), {"x": "a", "y": [1]})
        self.assertEqual(Point(), {})

    def test_declared_annotations_are_kept(self):
        self.assertEqual(Point.__annotations__, {"x": int, "y": int})

    def test_required_and_optional_keys(self):
        self.assertEqual(Point.__required_keys__, frozenset({"x", "y"}))
        self.assertEqual(Point.__optional_keys__, frozenset())
        self.assertEqual(Profile.__required_keys__, frozenset({"score"}))
        self.assertEqual(Profile.__optional_keys__, frozenset({"name", "age"}))

    def test_type_checking_on_typeddict_is_forbidden(self):
        with self.assertRaises(TypeError):
            isinstance(Point(x=1), Point)
        with self.assertRaises(TypeError):
            isinstance({}, Point)

    def test_get_type_hints_strips_qualifiers(self):
        self.assertEqual(get_type_hints(Point), {"x": int, "y": int})
        self.assertEqual(
            get_type_hints(Profile), {"name": str, "age": int, "score": float}
        )

    def test_explicit_runtime_key_check_replaces_class_check(self):
        self.assertEqual(render(Point(x=1, y=2)), "(1, 2)")
        with self.assertRaises(TypeError):
            render({"x": 1})
        with self.assertRaises(TypeError):
            render([1, 2])


if __name__ == "__main__":
    unittest.main()

