import inspect
import unittest
from typing import Protocol, runtime_checkable


@runtime_checkable
class Handler(Protocol):
    def handle(self, payload: str) -> str: ...


@runtime_checkable
class Named(Protocol):
    name: str


class Echo:
    def handle(self, payload):
        return "echo:" + payload


class WrongArity:
    def handle(self):
        return "?"


class Missing:
    def hello(self):
        return "hi"


class WithName:
    name = "x"


def register(handlers, name, handler):
    if not isinstance(handler, Handler):
        raise TypeError("对象缺少 handle 成员")
    try:
        inspect.signature(handler.handle).bind("payload")
    except TypeError as exc:
        raise TypeError(f"handle 签名不接受一个位置参数: {exc}") from exc
    handlers[name] = handler
    return handler


class ProtocolTest(unittest.TestCase):
    def test_member_presence_is_structural(self):
        self.assertTrue(isinstance(Echo(), Handler))
        self.assertFalse(isinstance(Missing(), Handler))

    def test_protocol_ignores_signature(self):
        self.assertTrue(isinstance(WrongArity(), Handler))
        self.assertTrue(issubclass(WrongArity, Handler))
        self.assertTrue(isinstance(Echo(), Handler))

    def test_register_rejects_missing_member(self):
        handlers = {}
        with self.assertRaises(TypeError):
            register(handlers, "missing", Missing())
        self.assertEqual(handlers, {})

    def test_register_rejects_incompatible_signature(self):
        handlers = {}
        with self.assertRaises(TypeError):
            register(handlers, "wrong", WrongArity())
        self.assertEqual(handlers, {})
        self.assertIs(register(handlers, "echo", Echo()), handlers["echo"])
        self.assertEqual(handlers["echo"].handle("ping"), "echo:ping")

    def test_data_protocol_supports_isinstance_not_issubclass(self):
        self.assertTrue(isinstance(WithName(), Named))
        with self.assertRaises(TypeError):
            issubclass(WithName, Named)

    def test_protocol_cannot_be_instantiated(self):
        with self.assertRaises(TypeError):
            Handler()


if __name__ == "__main__":
    unittest.main()

