from typing import Generic, TypeVar, get_args
import unittest

T = TypeVar("T")
Limited = TypeVar("Limited", int, str)
Bounded = TypeVar("Bounded", bound=int)


def first(items: list[T]) -> T:
    return items[0]


def last(items: list[T]) -> T:
    return items[-1]


class Box(Generic[T]):
    def __init__(self, item: T) -> None:
        self.item = item

    def get(self) -> T:
        return self.item

    def set(self, item: T) -> None:
        self.item = item


def constraints_of(tv):
    return tv.__constraints__


def bound_of(tv):
    return tv.__bound__


class TypeVarTest(unittest.TestCase):
    def test_typevar_is_runtime_object(self):
        self.assertEqual(type(T).__name__, "TypeVar")
        self.assertIsInstance(T, TypeVar)

    def test_generic_function_untouched_at_runtime(self):
        self.assertEqual(first([1, 2, 3]), 1)
        self.assertEqual(first(["a"]), "a")
        self.assertEqual(first([1, "a", 3.5]), 1)
        self.assertEqual(last([1, "a", 3.5]), 3.5)

    def test_constraints_and_bound(self):
        self.assertEqual(constraints_of(T), ())
        self.assertIsNone(bound_of(T))
        self.assertEqual(constraints_of(Limited), (int, str))
        self.assertEqual(constraints_of(Bounded), ())
        self.assertIs(bound_of(Bounded), int)

    def test_generic_class_metadata(self):
        self.assertEqual(Box.__parameters__, (T,))
        self.assertEqual(Box.__orig_bases__, (Generic[T],))
        self.assertEqual(get_args(list[T]), (T,))
        self.assertEqual(get_args(dict[str, T]), (str, T))

    def test_box_roundtrip(self):
        box = Box(1)
        self.assertEqual(box.get(), 1)
        box.set("a")
        self.assertEqual(box.get(), "a")


if __name__ == "__main__":
    unittest.main()

