from dataclasses import InitVar, dataclass, fields
from typing import ClassVar, Optional, get_type_hints
import unittest


@dataclass
class Config:
    name: str
    retries: int = 3
    source: ClassVar[str] = "env"
    raw: InitVar[Optional[str]] = None

    def __post_init__(self, raw):
        if raw is not None:
            self.name = raw


def field_names(cls):
    return [f.name for f in fields(cls)]


def item_hints(cls):
    return get_type_hints(cls)


class DataclassFieldsTest(unittest.TestCase):
    def test_classvar_and_initvar_are_not_fields(self):
        self.assertEqual(field_names(Config), ["name", "retries"])
        self.assertEqual([f.type for f in fields(Config)], [str, int])

    def test_initvar_flows_through_post_init(self):
        self.assertEqual(Config("a").name, "a")
        self.assertEqual(Config("a", raw="b").name, "b")
        self.assertNotIn("raw", Config("a").__dict__)

    def test_classvar_is_class_attribute(self):
        self.assertEqual(Config("a").source, "env")
        self.assertEqual(Config.source, "env")

    def test_hints_resolve_classvar_and_initvar(self):
        hints = item_hints(Config)
        self.assertEqual(hints["source"], ClassVar[str])
        self.assertIsInstance(hints["raw"], InitVar)

    def test_no_runtime_validation(self):
        self.assertEqual(Config(123).name, 123)
        self.assertEqual(Config(123).retries, 3)


