import dis
import inspect
import trace
from pathlib import Path


def wrong_format(cents):
    text = f"${cents // 100}.{cents % 100}"
    return text


def strict_format(cents):
    dollars, remainder = divmod(cents, 100)
    return f"${dollars}.{remainder:02d}"


def parse(text):
    try:
        return int(text)
    except ValueError:
        return -1


def executable_lines(func):
    # 去掉只有 RESUME 的 def 行，得到真正会产生行事件的语句行
    return {instr.positions.lineno for instr in dis.get_instructions(func)
            if instr.positions.lineno is not None and instr.opname != "RESUME"}


def lines_touched(func, *args):
    tracer = trace.Trace(count=True, trace=False)
    tracer.runfunc(func, *args)
    counts = tracer.results().counts
    filename = func.__code__.co_filename
    executed = {line for (fname, line) in counts if fname == filename}
    return executed & executable_lines(func), executable_lines(func)


def line_of(func, needle):
    source, start = inspect.getsourcelines(func)
    for offset, text in enumerate(source):
        if needle in text:
            return start + offset
    raise AssertionError(f"not found: {needle}")


def test_unasserted_call_reaches_every_executable_line():
    wrong_format(105)  # 只调用，不断言
    executed, executable = lines_touched(wrong_format, 105)
    assert executed == executable
    assert len(executable) == 2


def test_full_line_coverage_cannot_tell_wrong_from_right():
    executed_wrong, executable_wrong = lines_touched(wrong_format, 105)
    executed_right, executable_right = lines_touched(strict_format, 105)
    # 两个函数都拿到了 100% 行覆盖……
    assert executed_wrong == executable_wrong
    assert executed_right == executable_right
    # ……但覆盖率对结果对错一无所知
    assert wrong_format(105) == "$1.5"
    assert strict_format(105) == "$1.05"


def test_uncovered_except_branch_is_reported():
    executed, executable = lines_touched(parse, "42")
    except_line = line_of(parse, "except ValueError")
    assert except_line in executable
    assert except_line not in executed


def test_covering_the_error_path_closes_the_gap():
    executed, executable = lines_touched(parse, "oops")
    assert executed == executable


def test_reference_uses_only_stdlib_instrumentation():
