import unittest


class TaskRunnerError(Exception):
    """所有任务执行相关错误的基类，携带结构化字段。"""

    def __init__(self, message, stage, path=None):
        super().__init__(message)
        self.message = message
        self.stage = stage
        self.path = path


class ReadError(TaskRunnerError):
    pass


class ParseError(TaskRunnerError):
    pass


def load_line(path, lines):
    try:
        return lines[path]
    except KeyError as exc:
        raise ReadError("缺少输入: " + path, stage="read", path=path) from exc


def parse_int(path, lines):
    raw = load_line(path, lines)
    try:
        return int(raw)
    except ValueError as exc:
        raise ParseError("不是整数: " + path, stage="parse", path=path) from exc


def parse_int_quiet(path, lines):
    raw = load_line(path, lines)
    try:
        return int(raw)
    except ValueError:
        raise ParseError("不是整数: " + path, stage="parse", path=path) from None


class HierarchyTest(unittest.TestCase):
    def test_base_class_catches_read_error_with_fields(self):
        with self.assertRaises(TaskRunnerError) as ctx:
            load_line("a.txt", {})
        self.assertEqual(ctx.exception.stage, "read")
        self.assertEqual(ctx.exception.path, "a.txt")
        self.assertIsInstance(ctx.exception, ReadError)

    def test_specific_catch_does_not_catch_sibling(self):
        with self.assertRaises(ParseError):
            parse_int("a.txt", {"a.txt": "x"})
        try:
            parse_int("a.txt", {"a.txt": "x"})
        except ReadError:
            self.fail("ParseError 不应被 ReadError 捕获")
        except ParseError:
            pass

    def test_cause_is_original_value_error(self):
        with self.assertRaises(ParseError) as ctx:
            parse_int("a.txt", {"a.txt": "x"})
        err = ctx.exception
        self.assertIsInstance(err.__cause__, ValueError)
        self.assertTrue(err.__suppress_context__)
        self.assertIs(err.__context__, err.__cause__)
        self.assertEqual(str(err.__cause__), "invalid literal for int() with base 10: 'x'")

    def test_from_none_suppresses_context(self):
        with self.assertRaises(ParseError) as ctx:
            parse_int_quiet("a.txt", {"a.txt": "x"})
        err = ctx.exception
        self.assertIsNone(err.__cause__)
        self.assertIsInstance(err.__context__, ValueError)
        self.assertTrue(err.__suppress_context__)

    def test_reraising_with_from_exc_keeps_new_type(self):
        def boundary(path, lines):
            try:
                return parse_int(path, lines)
            except ParseError as exc:
                raise TaskRunnerError("任务失败", stage="run", path=path) from exc

        with self.assertRaises(TaskRunnerError) as ctx:
            boundary("a.txt", {"a.txt": "x"})
        self.assertEqual(ctx.exception.stage, "run")
        self.assertIsInstance(ctx.exception.__cause__, ParseError)
        self.assertIsInstance(ctx.exception.__cause__.__cause__, ValueError)

    def test_ok_path_returns_value(self):
        self.assertEqual(parse_int("a.txt", {"a.txt": "42"}), 42)


