import logging
import unittest


def get_logger(name):
    """库代码获取 logger 的唯一入口：只在目标 logger 上挂 NullHandler，不碰 root。"""
    logger = logging.getLogger(name)
    if not any(isinstance(h, logging.NullHandler) for h in logger.handlers):
        logger.addHandler(logging.NullHandler())
    return logger


class _Capture(logging.Handler):
    def __init__(self):
        super().__init__()
        self.records = []

    def emit(self, record):
        self.records.append(self.format(record))


class LibraryLoggerTest(unittest.TestCase):
    def setUp(self):
        self.root = logging.getLogger()
        self.saved_handlers = list(self.root.handlers)
        self.saved_level = self.root.level
        for name in ("pkg", "pkg.mod"):
            logging.getLogger(name).handlers.clear()
            logging.getLogger(name).setLevel(logging.NOTSET)
            logging.getLogger(name).propagate = True

    def tearDown(self):
        self.root.handlers[:] = self.saved_handlers
        self.root.setLevel(self.saved_level)

    def test_get_logger_does_not_touch_root(self):
        before = list(self.root.handlers)
        get_logger("pkg.mod")
        self.assertEqual(list(self.root.handlers), before)

    def test_null_handler_added_once(self):
        logger = get_logger("pkg.mod")
        self.assertTrue(any(isinstance(h, logging.NullHandler) for h in logger.handlers))
        count = len(logger.handlers)
        self.assertIs(get_logger("pkg.mod"), logger)
        self.assertEqual(len(logger.handlers), count)

    def test_hierarchy_parent_links(self):
        package = get_logger("pkg")
        module = get_logger("pkg.mod")
        self.assertEqual(module.parent, package)
        self.assertIs(package.parent, self.root)
        self.assertEqual(module.name, "pkg.mod")

    def test_effective_level_inherits_from_parent(self):
        package = get_logger("pkg")
        module = get_logger("pkg.mod")
        self.assertEqual(module.level, logging.NOTSET)
        self.assertEqual(module.getEffectiveLevel(), logging.WARNING)
        package.setLevel(logging.INFO)
        self.assertEqual(module.getEffectiveLevel(), logging.INFO)

    def test_records_filtered_by_effective_level(self):
        package = get_logger("pkg")
        module = get_logger("pkg.mod")
        handler = _Capture()
        handler.setFormatter(logging.Formatter("%(name)s:%(levelname)s:%(message)s"))
        package.addHandler(handler)
        package.setLevel(logging.WARNING)
        module.info("hidden")
        module.warning("shown")
        self.assertEqual(handler.records, ["pkg.mod:WARNING:shown"])

    def test_message_reaches_package_handler_via_propagation(self):
        package = get_logger("pkg")
        module = get_logger("pkg.mod")
        handler = _Capture()
        handler.setFormatter(logging.Formatter("%(name)s:%(levelname)s:%(message)s"))
        package.addHandler(handler)
        package.setLevel(logging.INFO)
        module.info("hello")
        self.assertEqual(handler.records, ["pkg.mod:INFO:hello"])


if __name__ == "__main__":
    unittest.main()

