import traceback
import unittest


def deep():
    raise ValueError("deep failure")


def middle():
    deep()


def wrap_cause():
    try:
        middle()
    except ValueError as exc:
        raise RuntimeError("wrap failed") from exc


def wrap_context():
    try:
        middle()
    except ValueError:
        raise RuntimeError("wrap failed")


def frame_names(exc):
    return [frame.name for frame in traceback.extract_tb(exc.__traceback__)]


def walk_names(exc):
    return [frame.f_code.co_name for frame, _ in traceback.walk_tb(exc.__traceback__)]


def render(exc, limit=None):
    return "".join(traceback.format_exception(exc, limit=limit))


def file_line_count(text):
    return sum(1 for line in text.splitlines() if line.strip().startswith("File "))


class _Capture(logging.Handler):
    def __init__(self):
        super().__init__()
        self.records = []

    def emit(self, record):
        self.records.append(record)


class TracebackTest(unittest.TestCase):
    def test_extract_tb_reaches_origin_frame(self):
        try:
            middle()
        except ValueError as exc:
            names = frame_names(exc)
            frames = traceback.extract_tb(exc.__traceback__)
            self.assertEqual(names[-2:], ["middle", "deep"])
            self.assertEqual(len(names), 3)
            self.assertEqual(frames[-1].line, 'raise ValueError("deep failure")')

    def test_walk_tb_yields_same_frames(self):
        try:
            middle()
        except ValueError as exc:
            self.assertEqual(walk_names(exc), frame_names(exc))

    def test_limit_truncates_frames(self):
        try:
            middle()
        except ValueError as exc:
            self.assertEqual(file_line_count(render(exc)), 3)
            self.assertEqual(file_line_count(render(exc, limit=1)), 1)
            self.assertTrue(render(exc, limit=1).strip().endswith("ValueError: deep failure"))

    def test_explicit_cause_sentence(self):
        try:
            wrap_cause()
        except RuntimeError as exc:
            text = render(exc)
            self.assertIn("The above exception was the direct cause of the following exception:", text)
            self.assertIsInstance(exc.__cause__, ValueError)

    def test_implicit_context_sentence(self):
        try:
            wrap_context()
        except RuntimeError as exc:
            text = render(exc)
            self.assertIn("During handling of the above exception, another exception occurred:", text)
            self.assertIsNone(exc.__cause__)
            self.assertIsInstance(exc.__context__, ValueError)

    def test_exc_info_outside_except_is_empty(self):
        try:
            middle()
        except ValueError:
            pass
        self.assertEqual(sys.exc_info(), (None, None, None))
        self.assertEqual(traceback.format_exc(), "NoneType: None\n")

