import ast
import dis
import subprocess
import sys
import textwrap
import unittest
from pathlib import Path
from tempfile import TemporaryDirectory


class BareExceptFinder(ast.NodeVisitor):
    def __init__(self):
        self.lines = []

    def visit_ExceptHandler(self, node):
        if node.type is None:
            self.lines.append(node.lineno)
        self.generic_visit(node)


def find_bare_excepts(source):
    finder = BareExceptFinder()
    finder.visit(ast.parse(source))
    return finder.lines


def function_names(source):
    return [node.name for node in ast.walk(ast.parse(source)) if isinstance(node, ast.FunctionDef)]


def has_assert_node(source):
    return any(isinstance(node, ast.Assert) for node in ast.walk(ast.parse(source)))


def opnames(func):
    return [item.opname for item in dis.get_instructions(func)]


def summarize_bytecode(code):
    return dis.Bytecode(code).dis().splitlines()


SAMPLE = '''def add_one(n):
    return n + 1


def guarded(value):
    try:
        return value
    except:
        return None
'''

PROBE = '''def validate(value):
    assert value > 0, "must be positive"
    return value


if __name__ == "__main__":
    print(validate(-5))
'''


def add_one(n):
    return n + 1


def validate(value):
    assert value > 0, "must be positive"
    return value


def run_child_probe(script, extra_args=()):
    return subprocess.run(
        [sys.executable, *extra_args, str(script)],
        capture_output=True,
        text=True,
    )


class DisAstTest(unittest.TestCase):
    def test_ast_walks_definitions_and_bare_excepts(self):
        self.assertEqual(function_names(SAMPLE), ["add_one", "guarded"])
        self.assertEqual(find_bare_excepts(SAMPLE), [8])
        self.assertEqual(find_bare_excepts("def f():\n    try:\n        pass\n    except ValueError:\n        pass\n"), [])
        self.assertTrue(has_assert_node(PROBE))

    def test_stable_instruction_names(self):
        ops = opnames(add_one)
        self.assertEqual(ops[0], "RESUME")
        self.assertEqual(ops[-1], "RETURN_VALUE")
        self.assertIn("BINARY_OP", ops)

    def test_bytecode_disassembly_is_text(self):
        text = dis.Bytecode(add_one).dis()
        self.assertEqual(len(text.splitlines()), len(opnames(add_one)) + 1)
        self.assertIn("RETURN_VALUE", text)
        self.assertTrue(text.startswith(" "))
        self.assertIs(dis.Bytecode(add_one).codeobj, add_one.__code__)

    def test_assert_node_survives_even_when_bytecode_drops_it(self):
        self.assertTrue(has_assert_node(PROBE))
        self.assertIn("RAISE_VARARGS", opnames(validate))
        optimized = dis.get_instructions(compile(textwrap.dedent(PROBE), "<probe>", "exec", optimize=2))
        self.assertTrue(all(item.opname != "RAISE_VARARGS" for item in optimized))

    def test_optimized_flag_skips_assert_at_runtime(self):
        with TemporaryDirectory() as tmp:
            script = Path(tmp) / "probe.py"
            script.write_text(PROBE, encoding="utf-8")
            plain = run_child_probe(script)
            optimized = run_child_probe(script, ("-O",))
            self.assertEqual(plain.returncode, 1)
            self.assertIn("AssertionError", plain.stderr)
            self.assertEqual(optimized.returncode, 0)
            self.assertEqual(optimized.stdout.strip(), "-5")


if __name__ == "__main__":
    unittest.main()
